"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["27136"],{69874(e){e.exports=JSON.parse('{"id":"FIN-1277","slug":"leveraged-loan","term":"Leveraged Loan","also_known_as":[],"difficulty":"Advanced","definition":"A leveraged loan is a loan made to a company that already has a high level of debt or a low credit rating, usually below investment grade, typically carrying a floating interest rate higher than loans to stronger borrowers.","explanation":["Leveraged loans are commonly used to finance leveraged buyouts by private equity firms, acquisitions, refinancing and payouts to shareholders. They are usually arranged as syndicated loans and secured against the borrower\'s assets.","Because borrowers are riskier, lenders charge higher interest rates, usually a benchmark rate plus a margin. For example, a leveraged loan might pay the benchmark rate plus 3.5 percentage points.","Many leveraged loans are bought by institutional investors, such as collateralized loan obligations, mutual funds and insurers, rather than held by banks. Over the past two decades, many have been issued as covenant-lite loans, with fewer protections for lenders.","Leveraged loans offer investors relatively high income and, because rates float, some protection against rising interest rates. But they carry significant credit risk, especially during economic downturns, when defaults rise. Regulators monitor the leveraged loan market closely because of its size and links to the wider financial system."],"note":"","total":1500,"prev":{"slug":"leveraged-buyout-lbo-model","term":"Leveraged Buyout (LBO) Model"},"next":{"slug":"levered-beta","term":"Levered Beta"}}')}}]);